CREATE TABLE "public"."fiscal_invoices" (
  "id"                        uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"                 uuid                     NOT NULL,
  "service_order_id"          uuid,
  "provider"                  text,
  "provider_invoice_id"       text,
  "provider_environment"      text                     DEFAULT 'sandbox'::text,
  "nfse_number"               text,
  "nfse_verification_code"    text,
  "nfse_status"               text                     NOT NULL DEFAULT 'pending'::text,
  "taker_document_type"       text,
  "taker_document"            text,
  "taker_name"                text                     NOT NULL,
  "taker_email"               text,
  "taker_phone"               text,
  "taker_zip_code"            text,
  "taker_address"             text,
  "taker_number"              text,
  "taker_complement"          text,
  "taker_neighborhood"        text,
  "taker_city"                text,
  "taker_state"               text,
  "service_code"              text,
  "service_description"       text                     NOT NULL,
  "service_amount"            numeric(12,2)            NOT NULL,
  "deduction_amount"          numeric(12,2)            DEFAULT 0,
  "tax_rate"                  numeric(5,2),
  "iss_amount"                numeric(12,2),
  "taxable_amount"            numeric(12,2),
  "cst"                       text,
  "c_class_trib"              text,
  "ind_natureza_op"           text,
  "v_bc_ibs_cbs"              numeric(12,2),
  "p_ibs_cbs"                 numeric(5,2),
  "v_ibs"                     numeric(12,2),
  "v_cbs"                     numeric(12,2),
  "provider_request_payload"  jsonb,
  "provider_response_payload" jsonb,
  "provider_error_message"    text,
  "pdf_url"                   text,
  "xml_url"                   text,
  "cancelled_at"              timestamp with time zone,
  "cancelled_by_user_id"      uuid,
  "cancellation_reason"       text,
  "cancellation_nfse_number"  text,
  "created_by_user_id"        uuid,
  "created_at"                timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"                timestamp with time zone,
  "issued_at"                 timestamp with time zone,
  CONSTRAINT "fiscal_invoices_nfse_status_check"
    CHECK ((nfse_status = ANY (ARRAY['pending'::text, 'processing'::text, 'authorized'::text, 'rejected'::text, 'cancelled'::text, 'error'::text]))),
  CONSTRAINT "fiscal_invoices_pkey" PRIMARY KEY (id),
  CONSTRAINT "fiscal_invoices_provider_environment_check" CHECK ((provider_environment = ANY (ARRAY['sandbox'::text, 'production'::text]))),
  CONSTRAINT "fiscal_invoices_taker_document_type_check" CHECK ((taker_document_type = ANY (ARRAY['cpf'::text, 'cnpj'::text])))
);

