CREATE OR REPLACE FUNCTION public.current_tenant_id()
  RETURNS text
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  AS $function$
BEGIN
  RETURN COALESCE(
    current_setting('request.jwt.claims', true)::jsonb -> 'app_metadata' ->> 'tenant_id',
    current_setting('request.jwt.claims', true)::jsonb -> 'user_metadata' ->> 'tenant_id',
    'matriz'
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.decrement_stock (
  item_id uuid,
  qty     integer
)
  RETURNS void
  LANGUAGE plpgsql
  AS $function$
BEGIN
  UPDATE inventory
  SET stock_quantity = stock_quantity - qty
  WHERE id = item_id AND stock_quantity >= qty;
END;
$function$;

CREATE OR REPLACE FUNCTION public.decrement_stock (
  p_item_id   uuid,
  p_tenant_id uuid,
  qty         integer
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  AS $function$
BEGIN
  UPDATE public.inventory
  SET stock_quantity = stock_quantity - qty
  WHERE id = p_item_id AND tenant_id = p_tenant_id AND stock_quantity >= qty;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_current_tenant_id()
  RETURNS text
  LANGUAGE sql
  STABLE
  AS $function$
  select nullif(current_setting('request.jwt.claims', true)::json->>'tenant_id', '')::text;
$function$;

CREATE OR REPLACE FUNCTION public.get_user_tenant_id()
  RETURNS uuid
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  AS $function$
    SELECT tenant_id FROM public.user_roles
    WHERE user_id = auth.uid()
    LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public.increment_stock (
  p_item_id   uuid,
  p_tenant_id uuid,
  qty         integer
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  AS $function$
BEGIN
  UPDATE public.inventory
  SET stock_quantity = stock_quantity + qty
  WHERE id = p_item_id AND tenant_id = p_tenant_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.is_superadmin()
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  AS $function$
    SELECT EXISTS (
        SELECT 1 FROM public.user_roles
        WHERE user_id = auth.uid() AND role = 'superadmin'
    );
$function$;

