CREATE VIEW "public"."v_service_orders_without_nfse" AS  SELECT id,
    tenant_id,
    contract_id,
    deceased_name,
    total_amount,
    burial_date,
    created_at,
    nfse_required
   FROM public.service_orders so
  WHERE ((status = 'completed'::text) AND (nfse_required = true) AND (nfse_id IS NULL) AND (NOT (EXISTS ( SELECT 1
           FROM public.fiscal_invoices fi
          WHERE ((fi.service_order_id = so.id) AND (fi.nfse_status = ANY (ARRAY['pending'::text, 'processing'::text, 'authorized'::text])))))));

