COMMENT ON COLUMN "public"."fiscal_invoices"."cst" IS 'Codigo de Situacao Tributaria - Reforma Tributaria (obrigatorio a partir de 01/10/2026).';

COMMENT ON COLUMN "public"."fiscal_invoices"."nfse_status" IS 'Status: pending, processing, authorized, rejected, cancelled, error.';

COMMENT ON COLUMN "public"."tenants"."asaas_api_key" IS 'API Key da conta/subconta Asaas da funerária para recebimento direto de mensalidades';

COMMENT ON COLUMN "public"."tenants"."asaas_environment" IS 'Ambiente de transação: sandbox ou production';

COMMENT ON COLUMN "public"."tenants"."asaas_wallet_id" IS 'ID da subconta Asaas (caso opere via split/white-label centralizado)';

COMMENT ON COLUMN "public"."tenants"."fiscal_auto_emit" IS 'Se true, emite NFS-e automaticamente quando uma OS e concluida.';

COMMENT ON COLUMN "public"."tenants"."fiscal_provider" IS 'Provedor de NFS-e: nfeio, enotas, focusnfe, tecnospeed.';

COMMENT ON TABLE "public"."fiscal_invoices" IS 'Historico de tentativas de emissao de NFS-e.';

